package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import java.sql.Timestamp;import org.springframework.jdbc.core.JdbcTemplate;import io.knowledgebrain.contracts.learning.githubevidence.v1.*;
final class GitHubEvidenceEvents {
 static void write(JdbcTemplate jdbc,UuidV7 ids,UUID space,UUID aggregate,UUID actor,String trace,Instant now,String topic,String artifact,String aggregateType,String type,byte[] payload){var event=GitHubLearningEventEnvelopeV1.newBuilder().setEventId(ids.next().toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("learning-service").setAggregateType(aggregateType).setAggregateId(aggregate.toString()).setSpaceId(space.toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(com.google.protobuf.ByteString.copyFrom(payload)).build();jdbc.update("INSERT INTO outbox_event VALUES (?,?,?,?,?,?,'learning',?,'1',?)",UUID.fromString(event.getEventId()),topic,aggregate,type,Timestamp.from(now),trace,artifact,event.toByteArray());}
 static void session(JdbcTemplate jdbc,UuidV7 ids,EvidenceSessionStore.Link v,UUID revision,UUID actor,String trace,Instant now){var p=GitHubEvidenceSessionChangedPayloadV1.newBuilder().setLinkId(v.linkId().toString()).setEvidenceId(v.evidenceId().toString()).setEvidenceKind("GITHUB").setRoadmapId(v.roadmapId().toString()).setNodeId(v.nodeId().toString()).setNodeTitle(v.nodeTitle()).setVisibility("PRIVATE").setState(v.state()).setVersion(v.version()).setRevisionId(revision.toString()).setCreatedAt(v.createdAt()).setUpdatedAt(v.updatedAt());if(v.sessionId()!=null)p.setSessionId(v.sessionId().toString()).setSessionVersion(v.sessionVersion()).setSessionNodeTitle(v.sessionNodeTitle()).setStartedAt(v.startedAt()).setEndedAt(v.endedAt()).setDurationSeconds(v.durationSeconds());write(jdbc,ids,v.spaceId(),v.linkId(),actor,trace,now,"github-evidence-session","github-evidence-session-events","GitHubEvidenceStudySession","GitHubEvidenceStudySessionChanged",p.build().toByteArray());}
}
